def replace_lab(content, lab_id, new_lab_str):
    start_idx = content.find(f"{{id:'{lab_id}'")
    if start_idx == -1: return content
    
    exp_idx = content.find("explanation:", start_idx)
    end_idx = content.find("},", exp_idx) + 2
    
    return content[:start_idx] + new_lab_str + content[end_idx:]

with open('src/pages/labs.tsx', 'r') as f:
    content = f.read()

# Using literal string replacements
lab_prom = "{id:'prometheus',title:'10 · Parse PromQL API JSON for SLO Alerts',prompt:'(Interview Scenario) A junior engineer is using string slicing to read Prometheus alerts. Upgrade this: Parse a raw Prometheus HTTP API JSON response (Vector type), extract the metric labels and values, and return a list of instances exceeding a 95% threshold.',starter:`import json\\nfrom typing import List, Dict\\n\\ndef evaluate_promql_response(raw_json: str, threshold: float = 95.0) -> List[str]:\\n    \\\"\\\"\\\"\\n    Parse the Prometheus JSON response.\\n    Navigate to data -> result.\\n    Extract the instance label if the float value exceeds the threshold.\\n    \\\"\\\"\\\"\\n    failing_instances = []\\n    # TODO: Implement JSON parsing\\n    return failing_instances\\n`,expected:\"A list of instance names that breached the threshold\",tests:`mock_response = \\\"\\\"\\\"\\n{\\n  \\\"status\\\": \\\"success\\\",\\n  \\\"data\\\": {\\n    \\\"resultType\\\": \\\"vector\\\",\\n    \\\"result\\\": [\\n      {\\\"metric\\\": {\\\"instance\\\": \\\"gpu-node-01\\\"}, \\\"value\\\": [1690000000, \\\"92.5\\\"]},\\n      {\\\"metric\\\": {\\\"instance\\\": \\\"gpu-node-02\\\"}, \\\"value\\\": [1690000000, \\\"98.1\\\"]},\\n      {\\\"metric\\\": {\\\"instance\\\": \\\"gpu-node-03\\\"}, \\\"value\\\": [1690000000, \\\"45.0\\\"]}\\n    ]\\n  }\\n}\\n\\\"\\\"\\\"\\nassert evaluate_promql_response(mock_response) == [\\\"gpu-node-02\\\"]\\nprint('PASS')`,hint:'Use json.loads(). Loop through payload. The value is a string at index 1 of the value list, so use float().',solution:`import json\\nfrom typing import List\\n\\ndef evaluate_promql_response(raw_json: str, threshold: float = 95.0) -> List[str]:\\n    try:\\n        payload = json.loads(raw_json)\\n    except json.JSONDecodeError:\\n        raise ValueError(\"Invalid JSON payload received from Prometheus\")\\n\\n    if payload.get(\"status\") != \"success\":\\n        raise RuntimeError(\"Prometheus query failed\")\\n        \\n    results = payload.get(\"data\", {}).get(\"result\", [])\\n    failing_instances = []\\n    \\n    for item in results:\\n        instance = item.get(\"metric\", {}).get(\"instance\", \"unknown\")\\n        # Prometheus values are always strings like \"98.1\", so cast to float\\n        val_str = item.get(\"value\", [0, \"0\"])[1]\\n        \\n        if float(val_str) >= threshold:\\n            failing_instances.append(instance)\\n            \\n    return failing_instances\\n\\nif __name__ == '__main__':\\n    # Mock PromQL HTTP API Response\\n    mock_response = \\\"\\\"\\\"\\n    {\\n      \\\"status\\\": \\\"success\\\",\\n      \\\"data\\\": {\\n        \\\"resultType\\\": \\\"vector\\\",\\n        \\\"result\\\": [\\n          {\\\"metric\\\": {\\\"instance\\\": \\\"dgx-node-1\\\"}, \\\"value\\\": [1700000000, \\\"99.9\\\"]},\\n          {\\\"metric\\\": {\\\"instance\\\": \\\"dgx-node-2\\\"}, \\\"value\\\": [1700000000, \\\"81.2\\\"]}\\n        ]\\n      }\\n    }\\n    \\\"\\\"\\\"\\n    breaches = evaluate_promql_response(mock_response, threshold=90.0)\\n    print(f\"Instances breaching threshold: {breaches}\")\\n`,explanation:'Senior engineers rarely rely on visual dashboards for automation. They programmatically query the Prometheus HTTP API, parse the strongly-typed JSON schemas (vector vs matrix types), cast string float values safely, and trigger remediation workflows (like cordoning a node) automatically based on the payload.'},"

lab_subproc = "{id:'subprocess',title:'11 · Safe Subprocess: nvidia-smi Execution',prompt:'(Interview Scenario) `os.system(\"nvidia-smi\")` is unsafe and blocks forever if the driver hangs. Write a senior-level wrapper using `subprocess.run` that executes `nvidia-smi --query-gpu=uuid,utilization.gpu --format=csv,noheader,nounits`, enforces a 2-second timeout, handles errors gracefully, and returns a dict mapping UUID to utilization integers.',starter:`import subprocess\\nfrom typing import Dict\\n\\ndef get_gpu_utilization() -> Dict[str, int]:\\n    \\\"\\\"\\\"\\n    Execute nvidia-smi with query arguments.\\n    Return a dict like {\\\"GPU-abcd\\\": 45, \\\"GPU-efgh\\\": 99}\\n    Must use a 2.0 second timeout.\\n    \\\"\\\"\\\"\\n    utils = {}\\n    # TODO: Implement subprocess.run logic\\n    return utils\\n`,expected:\"A dictionary mapping UUIDs to integers, or raising TimeoutExpired\",tests:`import sys\\nimport subprocess\\nclass MockProc:\\n    def __init__(self): self.stdout = \"GPU-1111, 45\\nGPU-2222, 99\\n\"\\nsubprocess.run = lambda *args, **kwargs: MockProc()\\n\\nresult = get_gpu_utilization()\\nassert result == {\"GPU-1111\": 45, \"GPU-2222\": 99}, f\"Got {result}\"\\nprint('PASS')`,hint:'Use `subprocess.run([\"nvidia-smi\", \"--query-gpu=...\"], capture_output=True, text=True, timeout=2.0)`. Split `proc.stdout` by newlines and commas.',solution:`import subprocess\\nimport logging\\nfrom typing import Dict\\n\\nlogger = logging.getLogger(__name__)\\n\\ndef get_gpu_utilization() -> Dict[str, int]:\\n    cmd = [\\n        \"nvidia-smi\", \\n        \"--query-gpu=uuid,utilization.gpu\", \\n        \"--format=csv,noheader,nounits\"\\n    ]\\n    try:\\n        # check=True raises CalledProcessError on exit code != 0\\n        # timeout=2.0 prevents infinite hangs if the driver is locked up\\n        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=2.0, check=True)\\n    except subprocess.TimeoutExpired:\\n        logger.error(\"nvidia-smi timed out. The NVIDIA driver may be hung (D-state).\")\\n        raise\\n    except subprocess.CalledProcessError as e:\\n        logger.error(f\"nvidia-smi failed with exit code {e.returncode}: {e.stderr}\")\\n        raise\\n        \\n    utils = {}\\n    for line in proc.stdout.strip().split('\\n'):\\n        if not line: continue\\n        parts = line.split(',')\\n        if len(parts) == 2:\\n            uuid = parts[0].strip()\\n            util = int(parts[1].strip())\\n            utils[uuid] = util\\n            \\n    return utils\\n\\nif __name__ == '__main__':\\n    # Note: In the browser playground this uses a mock, but on a real Linux box it executes real commands.\\n    try:\\n        stats = get_gpu_utilization()\\n        print(f\"Live GPU Utilization: {stats}\")\\n    except Exception as e:\\n        print(f\"Error querying GPUs: {e}\")\\n`,explanation:'Calling shell commands is a major source of production outages. `os.system` or `subprocess.Popen` without timeouts will hang forever if the underlying hardware (like a GPU driver) locks up, exhausting worker threads. Senior engineers always use `subprocess.run` with explicit `timeout=`, `check=True`, and `capture_output=True` to parse exact CLI stdout safely.'},"

lab_oom = "{id:'oom',title:'13 · Parse Linux Syslog for cgroup OOMs',prompt:'(Interview Scenario) Pods are restarting with Exit Code 137. Container orchestrators mask OOMs. Write a function that parses raw `dmesg` or `/var/log/syslog` lines, identifies \"Memory cgroup out of memory\" events, and extracts the invoked process name and PID using regex.',starter:`import re\\nfrom typing import List, Dict\\n\\ndef parse_oom_kills(syslog_content: str) -> List[Dict[str, str]]:\\n    \\\"\\\"\\\"\\n    Look for lines like: \\n    \"Memory cgroup out of memory: Killed process 12345 (python3) total-vm:...\"\\n    Return a list of dicts: [{\"pid\": \"12345\", \"process\": \"python3\"}]\\n    \\\"\\\"\\\"\\n    kills = []\\n    # TODO: Implement regex parsing\\n    return kills\\n`,expected:\"A list of dictionaries with extracted PID and process name\",tests:`mock_log = \\\"\\\"\\\"\\nSep 10 14:00:01 node-1 kernel: [ 100.0] Memory cgroup out of memory: Killed process 5555 (train.py) total-vm:...\\nSep 10 14:05:00 node-1 kernel: [ 200.0] Out of memory: Killed process 9999 (java) total-vm:...\\n\\\"\\\"\\\"\\nresults = parse_oom_kills(mock_log)\\nassert len(results) == 2\\nassert results[0][\"pid\"] == \"5555\" and results[0][\"process\"] == \"train.py\"\\nassert results[1][\"pid\"] == \"9999\" and results[1][\"process\"] == \"java\"\\nprint('PASS')`,hint:'Use a regex pattern like `Killed process (\\\\d+) \\\\(([^)]+)\\\\)`. Use `re.finditer` over the log content.',solution:`import re\\nfrom typing import List, Dict\\n\\ndef parse_oom_kills(syslog_content: str) -> List[Dict[str, str]]:\\n    kills = []\\n    # Regex captures the digits for PID, and anything inside the parentheses for the process name\\n    pattern = re.compile(r\"out of memory: Killed process (?P<pid>\\d+) \\\\((?P<proc>[^)]+)\\\\)\", re.IGNORECASE)\\n    \\n    for match in pattern.finditer(syslog_content):\\n        kills.append({\\n            \"pid\": match.group(\"pid\"),\\n            \"process\": match.group(\"proc\")\\n        })\\n        \\n    return kills\\n\\nif __name__ == '__main__':\\n    mock_dmesg = \\\"\\\"\\\"\\n[32145.67] Memory cgroup out of memory: Killed process 10230 (resnet_train.py) total-vm:64000kB\\n[32150.12] Out of memory: Killed process 105 (systemd-journal) total-vm:2000kB\\n    \\\"\\\"\\\"\\n    oom_events = parse_oom_kills(mock_dmesg)\\n    for event in oom_events:\\n        print(f\"CRITICAL: Process {event['process']} (PID {event['pid']}) was OOM Killed by the Linux kernel.\")\\n`,explanation:'When Kubernetes reports `OOMKilled` (Exit Code 137), the K8s events log lacks context on *which* subprocess spiked memory. Senior engineers bypass the orchestrator and parse `/var/log/syslog` or `dmesg` to find the exact kernel `cgroup` kill invocation, determining whether the main app or a rogue sidecar consumed the RAM.'},"

lab_bmc = "{id:'bmc-sensors',title:'21 · Redfish API: Parse BMC Thermal Sensors',prompt:'(Interview Scenario) You query a DGX BMC via the Redfish API for thermal data. The response is a massive nested JSON payload. Write a robust parser that iterates through the `Temperatures` list, handles missing `UpperThresholdCritical` keys gracefully using `.get()`, and returns a list of failing sensor names.',starter:`import json\\nfrom typing import List\\n\\ndef find_overheating_sensors(redfish_json: str) -> List[str]:\\n    \\\"\\\"\\\"\\n    Parse the Redfish JSON.\\n    Navigate to 'Temperatures'.\\n    For each sensor, if 'ReadingCelsius' >= 'UpperThresholdCritical', record its 'Name'.\\n    Ignore sensors missing 'ReadingCelsius' or 'UpperThresholdCritical'.\\n    \\\"\\\"\\\"\\n    failing = []\\n    # TODO: Implement Redfish JSON parsing\\n    return failing\\n`,expected:\"A list of sensor names that are overheating\",tests:`mock_redfish = \\\"\\\"\\\"\\n{\\n  \\\"Temperatures\\\": [\\n    {\\\"Name\\\": \\\"CPU0\\\", \\\"ReadingCelsius\\\": 85, \\\"UpperThresholdCritical\\\": 90},\\n    {\\\"Name\\\": \\\"GPU1\\\", \\\"ReadingCelsius\\\": 95, \\\"UpperThresholdCritical\\\": 92},\\n    {\\\"Name\\\": \\\"DIMM_A\\\", \\\"ReadingCelsius\\\": 40}\\n  ]\\n}\\n\\\"\\\"\\\"\\nassert find_overheating_sensors(mock_redfish) == [\"GPU1\"]\\nprint('PASS')`,hint:'Load the JSON. Iterate `payload.get(\"Temperatures\", [])`. Extract reading and threshold. If both are not `None` and reading >= threshold, append the name.',solution:`import json\\nfrom typing import List\\n\\ndef find_overheating_sensors(redfish_json: str) -> List[str]:\\n    try:\\n        payload = json.loads(redfish_json)\\n    except json.JSONDecodeError:\\n        raise ValueError(\"Invalid JSON from BMC Redfish API\")\\n        \\n    failing_sensors = []\\n    temperatures = payload.get(\"Temperatures\", [])\\n    \\n    for sensor in temperatures:\\n        name = sensor.get(\"Name\", \"Unknown Sensor\")\\n        reading = sensor.get(\"ReadingCelsius\")\\n        critical_limit = sensor.get(\"UpperThresholdCritical\")\\n        \\n        # Hardware sensors frequently drop readings or lack thresholds.\\n        # Explicitly checking for None prevents TypeError exceptions.\\n        if reading is not None and critical_limit is not None:\\n            if reading >= critical_limit:\\n                failing_sensors.append(name)\\n                \\n    return failing_sensors\\n\\nif __name__ == '__main__':\\n    # Mock output from a curl call to /redfish/v1/Chassis/1/Thermal\\n    mock_api_response = \\\"\\\"\\\"\\n    {\\n      \\\"Temperatures\\\": [\\n        {\\\"Name\\\": \\\"NVIDIA HGX Baseboard\\\", \\\"ReadingCelsius\\\": 70, \\\"UpperThresholdCritical\\\": 85},\\n        {\\\"Name\\\": \\\"Infiniband ConnectX-7\\\", \\\"ReadingCelsius\\\": 102, \\\"UpperThresholdCritical\\\": 100},\\n        {\\\"Name\\\": \\\"Ambient Front\\\", \\\"ReadingCelsius\\\": null, \\\"UpperThresholdCritical\\\": 40}\\n      ]\\n    }\\n    \\\"\\\"\\\"\\n    alarms = find_overheating_sensors(mock_api_response)\\n    for alarm in alarms:\\n        print(f\"HARDWARE ALERT: {alarm} exceeds critical thermal limits!\")\\n`,explanation:'BMC (Baseboard Management Controller) Redfish APIs return notorious amounts of inconsistent data. Hardware sensors occasionally return `null` or omit threshold fields entirely. A senior engineer defensively parses nested dictionaries using `.get(key, default)` and `is not None` to prevent a missing sensor reading from crashing the entire fleet-monitoring pipeline.'},"

content = replace_lab(content, 'prometheus', lab_prom)
content = replace_lab(content, 'subprocess', lab_subproc)
content = replace_lab(content, 'oom', lab_oom)
content = replace_lab(content, 'bmc-sensors', lab_bmc)

with open('src/pages/labs.tsx', 'w') as f:
    f.write(content)
